"""Step 2026-10-17 (PESTLE): link the PESTLE tool in the hub (index.html) from the start. Every anchor must match once.
    python3 tests/build/patch_hub_pestle.py index.html
Then serve the platform folder and run tests/build/demo_pestle.py, which fills DEMO_RES.pestle from the hub's own reading of the PESTLE example
(until then a placeholder with st "none" stands in). The other adapters (swotAd, lessonsAd, qtAd …) are left as they are, so the snapshots the hub
reads for the other tools do not change. PESTLE goes into Audit & Improvement with the rest of the toolbox, next to SWOT (15 rows there, 38 in
all): it is built on the toolbox engine and feeds SWOT, while the Strategy & Performance Studio keeps its own PESTLE register."""
import sys, os

HERE = os.path.dirname(os.path.abspath(__file__))
path = sys.argv[1] if len(sys.argv) > 1 else os.path.join(HERE, "..", "..", "index.html")
s = open(path, encoding="utf-8").read()
if 'pestle:   "./modules/pestle.html"' in s:
    print("PESTLE already linked; nothing to do"); sys.exit(0)


def rep(old, new):
    global s
    n = s.count(old)
    assert n == 1, (n, old[:100])
    s = s.replace(old, new)


# 1. URL
rep('  swot:     "./modules/swot.html"\n};', '  swot:     "./modules/swot.html",\n  pestle:   "./modules/pestle.html"\n};')
# 2. systems: Audit & Improvement row (after SWOT)
