rep('''/* ---------- registry ---------- */''', '''/* ---------- PESTLE scans (cia-pestle:v1). The score (significance × certainty), the top items (the six highest scores of 6 or more; ties by
   significance, then by order of entry), the source rule (a source and its date), the generic-item rule, the outcome rule (a SWOT study id and its
   quadrant; a reference or an entry in the register or the plan; an entry for the Risk Studio; or a reason to set it aside), the climate decision and
   the review rule are the tool's own rules (modules/pestle.html). ---------- */
function pestleAd(S){
  if(!S) return finish([],null,false);
  const Q=["IN1","IN2","IN3","EV1","EV2","EV3","OU1","OU2","OU3","RV1","RV2","RV3"], A=(S.assess&&typeof S.assess==="object")?S.assess:{};
  const R=(arr(S.records)||[]).filter(r=>r&&typeof r==="object");
  const ans=Q.filter(q=>num(A[q])!=null), pct=qs=>{ const s=qs.reduce((a,q)=>a+(num(A[q])||0),0); return s/(2*qs.length)*100; };
  const tx=v=>String(v==null||typeof v==="object"?"":v).trim(), isD=d=>/^\\d{4}-\\d{2}-\\d{2}$/.test(String(d||""));
  const L2=v=>(Array.isArray(v)?v:[]).filter(x=>x&&typeof x==="object"), BG=["p","e","s","t","l","en"], AG=BG.concat(["x1","x2","x3"]);
  const W=v=>{ const n=parseInt(v,10); return n>=1&&n<=5?n:0; };
  const GEN=/(uncertain|uncertainty|unstable|instability|volatil|fluctuat|changing|competition is|economic (conditions|situation)|the economy|market conditions|غير مستقر|عدم ال?يقين|عدم ال?استقرار|متغير|تقلب|تذبذب|الظروف الاقتصادية|الوضع الاقتصادي|المنافسة|تغيرات)/i;
  const gen=f=>{ const t=tx(f.t); if(!t||/[0-9٠-٩]/.test(t)) return false; return GEN.test(t)||t.split(/\\s+/).length<4; };
  const read=r=>{ const F=L2(r.fac).filter(f=>tx(f.t)).map(f=>({id:tx(f.id),g:AG.indexOf(f.g)>=0?f.g:"p",t:f.t,so:tx(f.so),d:f.d,sig:W(f.sig),cer:W(f.cer),eff:["o","t","b"].indexOf(f.eff)>=0,hz:["s","m","lg"].indexOf(f.hz)>=0}));
    const sc=f=>f.sig&&f.cer?f.sig*f.cer:0, by={}; F.forEach(f=>{ by[f.id]=f; });
    const T=F.map((f,k)=>[f,k]).filter(x=>sc(x[0])>0).sort((a,b)=>(sc(b[0])-sc(a[0]))||(b[0].sig-a[0].sig)||(a[1]-b[1])).map(x=>x[0]).filter(f=>sc(f)>=6).slice(0,6);
    const src=f=>!!f.so&&isD(f.d);
    const ok=o=>{ if(!by[tx(o.f)]) return false; const to=["swot","reg","plan","iso31000","aside"].indexOf(o.to)>=0?o.to:"swot";
      if(to==="swot") return !!tx(o.ref)&&(o.q==="o"||o.q==="t"); if(to==="reg"||to==="plan") return !!(tx(o.ref)||tx(o.what)); if(to==="iso31000") return !!(tx(o.what)||tx(o.ref)); return !!tx(o.why); };
    const O=L2(r.outs), cov=f=>O.some(o=>tx(o.f)===f.id&&ok(o));
    const G=L2(r.grp), nr=k=>G.some(g=>g.k===k&&!!tx(g.nr));
    const team=L2(r.team).filter(m=>tx(m.n)&&tx(m.role)), V=L2(r.revs).filter(v=>isD(v.date)).sort((a,b)=>a.date<b.date?-1:(a.date>b.date?1:0)), lv=V.length?V[V.length-1]:null;
    const c=(r.clim&&typeof r.clim==="object")?r.clim:{};
    return {top:T.length, topSrc:T.filter(src).length, topOut:T.filter(cov).length, rev:!!lv&&(!isD(r.date)||lv.date>=r.date)&&!!tx(lv.chg),
            team:team.length<3||!team.some(m=>m.ext&&m.ext!=="no"), grp:F.length>0&&BG.some(k=>!F.some(f=>f.g===k)&&!nr(k)), src:F.some(f=>!src(f)),
            gen:T.some(gen), clim:F.length>0&&!((c.dec==="rel"||c.dec==="not")&&!!tx(c.why)), rate:F.some(f=>!(f.sig&&f.cer&&f.eff&&f.hz)), uncov:T.some(f=>!cov(f))}; };
  let top=0, topSrc=0, topOut=0, rev=0, tm=0, gr=0, sr=0, ge=0, cl=0, ra=0, un=0;
  R.forEach(r=>{ const x=read(r); top+=x.top; topSrc+=x.topSrc; topOut+=x.topOut; if(x.rev) rev++; if(x.team) tm++; if(x.grp) gr++; if(x.src) sr++; if(x.gen) ge++; if(x.clim) cl++; if(x.rate) ra++; if(x.uncov) un++; });
  const m=[ M("peAs", ans.length? pct(Q) : null, "perf", ans.length? `${Math.round(pct(Q))}%` : ""),
            M("peSrc", top? share(topSrc,top) : null, "perf", top? frac(topSrc,top) : ""),
            M("peOut", top? share(topOut,top) : null, "prog", top? frac(topOut,top) : ""),
            M("peRev", R.length? share(rev,R.length) : null, "prog", R.length? frac(rev,R.length) : ""),
            M("an", ans.length? share(ans.length,Q.length) : null, "prog", frac(ans.length,Q.length)) ];
  const IT=[[B("Team under three roles or with no outside input","فريق أقل من ثلاثة أدوار أو بلا رأي خارجي"),tm,"#1E8C93"],[B("A PESTLE factor not looked at (no item, no reason)","عامل من العوامل الستة لم يُدرس (لا بند ولا سبب)"),gr,"#7B5BB8"],
            [B("Items with no source or date","بنود بلا مصدر أو تاريخ"),sr,"#3563C9"],[B("Generic items among the top","بنود عامة بين البنود العليا"),ge,"#B7790F"],
            [B("Climate change not decided, or no reason","تغير المناخ لم يُقرر، أو بلا سبب"),cl,"#2F7D4B"],[B("Items not fully rated","بنود بلا تقييم كامل"),ra,"#1B2A4A"],
            [B("Top items with no outcome","بنود عليا بلا مخرج"),un,"#C9821A"]];
  const bd = R.length ? {t:BDT.pestle, items:IT.map(([l,n,col])=>({l, v:share(n,R.length), t:String(n), col}))} : null;
  return finish(m, bd, ans.length>0 || R.length>0);
}

/* ---------- registry ---------- */''')
